# Canvas: phonetic_entities_v1
# Path: app/features/phonetic_correction/domain/entities.py

import uuid
from typing import List
from datetime import datetime, timezone
from pydantic import BaseModel, Field, ConfigDict

# Inheriting the clean sentences generated by Phase 7
from app.features.sentence_reconstruction.domain.entities import ReconstructedSentence


class PhoneticPatch(BaseModel):
    """
    Represents a single read-only correction generated by the LLM.
    The AI is strictly bound to returning an array of these objects.
    """
    original: str = Field(description="The exact misspelled string found in the text.")
    correction: str = Field(description="The corrected domain terminology.")

    model_config = ConfigDict(frozen=True)


class AppliedCorrectionRecord(BaseModel):
    """
    An immutable audit record proving exactly what the Orchestrator changed.
    Crucial for legal and medical compliance to prove no hallucination occurred.
    """
    sentence_id: uuid.UUID
    original_text: str
    corrected_text: str
    applied_patches: List[PhoneticPatch]

    model_config = ConfigDict(frozen=True)


class PhoneticCorrectedTranscript(BaseModel):
    """
    The Final Aggregate Root for Phase 8.
    Contains the fully corrected RAG-ready sentences and the cryptographic-style audit trail.
    """
    id: uuid.UUID = Field(default_factory=uuid.uuid4)
    source_id: uuid.UUID

    sentences: List[ReconstructedSentence] = Field(default_factory=list)
    audit_trail: List[AppliedCorrectionRecord] = Field(default_factory=list)

    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))

    model_config = ConfigDict(from_attributes=True)